package com.talentmatch.ai;

import java.util.List;

/**
 * Explanations for a list of requests.
 *
 * @param results   one result per request, in input order
 * @param generated AI explanations generated by flights this call started
 */
public record ExplanationResults(List<ExplanationResult> results, int generated) {

    public ExplanationResults {
        results = List.copyOf(results);
    }
}
